pageSchema.innerStyle:
.wk-org-page {
  height: 100%;
  .wk-org-header {
    line-height: 42px;
    text-align: right;
    &.with-collapse {
      .i-wrapper__container__footer {
        border-left: 1px solid var(--el-border-color-lighter);
      }
    }
    &>.i-wrapper__container__body {
      position: fixed;
      top: calc(60px + var(--i-admin-header-height));
      width: -webkit-fill-available;
      margin-left: -19px;
      z-index: 10;
      background: var(--el-fill-color-lighter);
      padding: 0 20px;
    }
    &>.i-wrapper__container__footer {
      position: fixed;
      right: 0;
      top: 132px;
      width: 260px;
      .el-tab-pane {
        height: calc(100vh - 230px);
        overflow-y: auto;
      }
    }
  }
  .wk-org-header.with-collapse + .wk-org-form__wrapper {
    padding-right: 260px;
  }
  .wk-org-header__title {
    font-size: 16px;
    font-weight: bold;
  }
  .wk-org-form__wrapper {
    padding-top: 30px;
  }
  .wk-org__languages__wrapper {
    height: calc(100vh - 180px);
    padding: 0 10px 50px 10px;
  }
  .wk-org__version-cards {
    padding: 0 10px 50px 10px;
    .el-col {
      margin-bottom: 0;
    }
    .el-card {
      border: none;
    }
    .el-pagination {
      position: fixed;
      bottom: 50px;
      background: var(--el-bg-color);
    }
    .i-card__body {
      padding: 0;
    }
  }
  .wk-org__version-tags {
    position: absolute;
    right: 30px;
    top: 12px;
  }
  .wk-org__version-collapse {
    border-bottom: 0;
    overflow: hidden;
    .i-collapse__container__title {
      display: none;
    }
    .i-collapse__container__actions {
      left: -10px;
      text-align: left;
    }
    .el-collapse-item {
      &:hover {
        .el-collapse-item__header,
        .el-collapse-item__wrap {
          background: var(--el-color-primary-light-9);
        }
      }
    }
  }
  .wk-org__language-item {
    padding: 0 20px;
    text-align: left;
    cursor: pointer;
    &:hover {
      background: var(--el-color-primary-light-9);
    }
  }
  .wk-org__language-name {
    font-weight: bold;
  }
  .wk-org__language-icon {
    border: 1px solid var(--el-border-color-lighter);
    font-size: 12px;
    padding: 4px;
    margin-right: 10px;
  }
  .wk-org__language-tag {
    position: absolute;
    right: 20px;
    top: 12px;
  }
  .wk-org__history-icon {
    position: absolute;
    right: 20px;
    top: 12px;
  }
  .wk-org__history-text {
    padding: 0 10px 10px 20px;
  }
  .demo-grid-form {
    .i-form__container__fieldset__items {
      display: grid;
      grid-template-columns: repeat(3, 33.3%);
    }
    .field-1,
    .field-4,
    .field-7,
    .field-10 {
      padding-right: 20px;
    }
    .field-2,
    .field-5,
    .field-8,
    .field-11 {
      padding: 0 10px;
    }
    .field-3,
    .field-6,
    .field-9,
    .field-12 {
      padding-left: 20px;
    }
  }
}
